  function playerTeam(pOrIndex){
    if(pOrIndex&&typeof pOrIndex==='object'&&Number.isInteger(Number(pOrIndex.team)))return Number(pOrIndex.team);
    const idx=Number(pOrIndex);if(Number.isInteger(idx)){const p=r.world?.players?.find?.(x=>Number(x.index)===idx);if(p&&Number.isInteger(Number(p.team)))return Number(p.team);if(r.match?.mode==='siege')return idx===0?0:1;}
    return 0;
  }
  function localTeam(){return playerTeam(localPlayer()||localIndex());}
  function enemyTeam(team){return Number(team)===0?1:0;}
