  function shotSfxId(id){return WEAPONS[id]?`weapon:${id}`:'weapon:pistol';}
  function announcerVoiceScore(v){
    const name=String(v?.name||'').toLowerCase(),lang=String(v?.lang||'').toLowerCase();let score=0;
    if(/^en([_-]|$)/i.test(lang))score+=100;else if(lang.includes('en'))score+=55;else score-=180;
    if(/en[-_]?us/.test(lang))score+=20;else if(/en[-_]?(gb|au|ca|ie|nz)/.test(lang))score+=10;
    if(/aria|jenny|zira|samantha|victoria|karen|moira|fiona|tessa|serena|susan|hazel|linda|ava|emma|olivia|joanna|kendra|kimberly|salli|amy|nicole|natasha|sonia|libby|maisie|female/.test(name))score+=100;
    if(/neural|natural|premium|enhanced|online/.test(name))score+=34;
    if(/microsoft/.test(name))score+=12;if(/google/.test(name))score+=9;if(/apple/.test(name))score+=7;
    if(/guy|david|mark|daniel|alex|fred|ralph|bruce|tom|lee|male|george|james|ryan|aaron|arthur|oliver|andrew|brian|christopher/.test(name))score-=130;
    if(v?.default)score+=2;return score;
  }
  function announcerVoice(){
    const synth=window.speechSynthesis;if(!synth)return null;const voices=synth.getVoices?.()||[];if(!voices.length)return r.announcerVoice||null;
    if(r.announcerVoice&&voices.includes(r.announcerVoice)&&announcerVoiceScore(r.announcerVoice)>=90)return r.announcerVoice;
    const ranked=[...voices].sort((a,b)=>announcerVoiceScore(b)-announcerVoiceScore(a));const best=ranked[0]||null;r.announcerVoice=best;return best;
  }
