    const k=String(e.key||'').toLowerCase();
    if(k==='h'&&!e.repeat){e.preventDefault();if(r.scoreboardExpanded)closeScoreboardFull();if(r.defenseExpanded)closeDefenseFull();if(r.minimapExpanded)closeMinimapFull();toggleHudVisibility();return;}
