  function drawPickups(c,map){
    const t=now(),size=cameraViewSize();for(const p of r.world.pickups||[]){if(!p.active)continue;const s=worldToScreen(p.x,p.y);if(s.x<-55||s.y<-55||s.x>size.w+55||s.y>size.h+55)continue;const w=weapon(p.weapon),pulse=.88+Math.sin(t/240+p.id)*.08;
      c.save();c.translate(s.x,s.y);c.scale(pulse,pulse);c.fillStyle='rgba(3,11,18,.86)';c.strokeStyle=w.color;c.lineWidth=2;c.shadowColor=w.color;c.shadowBlur=18;c.beginPath();c.arc(0,0,21,0,Math.PI*2);c.fill();c.stroke();c.shadowBlur=0;drawWeaponGlyph(c,w,.72);c.fillStyle=w.color;c.font='900 8px system-ui';c.textAlign='center';c.fillText(w.name,0,35);c.restore();}
  }
  function drawHealthPickups(c,map){
    const t=now(),size=cameraViewSize();for(const h of r.world.healthPickups||[]){if(!h.active)continue;const s=worldToScreen(h.x,h.y);if(s.x<-50||s.y<-50||s.x>size.w+50||s.y>size.h+50)continue;const pulse=.92+Math.sin(t/220+h.id)*.08;c.save();c.translate(s.x,s.y);c.scale(pulse,pulse);c.shadowColor='#61ffc2';c.shadowBlur=20;c.fillStyle='rgba(5,35,28,.9)';c.strokeStyle='#6fffc5';c.lineWidth=2;c.beginPath();c.arc(0,0,20,0,Math.PI*2);c.fill();c.stroke();c.shadowBlur=0;c.fillStyle='#caffea';c.fillRect(-3,-11,6,22);c.fillRect(-11,-3,22,6);c.fillStyle='#6fffc5';c.font='900 8px system-ui';c.textAlign='center';c.fillText(`+${Number(h.amount)||25} HP`,0,34);c.restore();}
  }

